"""Prepare OpenPhotoEdit for an episode.

The OpenPhotoEdit tasks edit source images kept in a fixture directory on the
guest Desktop and export the results beside them.  Preparation confirms the
fixture directory carries the two calibration sources and its manifest, and that
the exports the task asks for have not been written yet -- an export left over
from an earlier run would be indistinguishable from a finished task.  It opens
no source image and writes nothing.
"""

from __future__ import annotations

from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: Where the calibration sources live, relative to the guest home directory.
DEFAULT_FIXTURE_DIR = "~/Desktop/PhotoFixtures"


class OpenPhotoEditInitializer(MacAppInitializer):
    """Confirm the OpenPhotoEdit fixture and export starting point."""

    INITIALIZER_ID = "initializers.macos.openphotoedit:OpenPhotoEditInitializer"
    APP_NAME = "OpenPhotoEdit"
    BUNDLE_ID = "com.killt.openphotoedit"
    SETTLE_MS = 2000

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        fixture_dir = str(params.get("fixture_dir") or DEFAULT_FIXTURE_DIR)
        expected_files = [str(name) for name in (params.get("expected_files") or [])]
        expected_exports = [str(name) for name in (params.get("expected_exports") or [])]
        manifest = str(params.get("manifest_name") or "")

        def listing(directory: str) -> dict[str, Any]:
            script = "\n".join(
                [
                    "import json",
                    "from pathlib import Path",
                    f"root = Path({directory!r}).expanduser()",
                    "names = sorted(p.name for p in root.iterdir()) if root.is_dir() else []",
                    "print(json.dumps({'path': str(root), 'exists': root.is_dir(), 'names': names}))",
                ]
            )
            return self._guest_json(controller, script, what="the fixture directory")

        fixtures = listing(fixture_dir)
        if not fixtures.get("exists"):
            raise InitializationError(
                f"the OpenPhotoEdit fixture directory is missing at {fixtures.get('path')}"
            )
        present = set(fixtures.get("names") or [])
        missing = [name for name in expected_files if name not in present]
        if missing:
            raise InitializationError(
                "the fixture directory does not carry the calibration source(s) "
                + ", ".join(missing)
            )
        if manifest and manifest not in present:
            raise InitializationError(f"the fixture directory carries no {manifest}")

        exports = listing(str(params.get("export_dir") or fixture_dir))
        export_names = set(exports.get("names") or [])
        stale = [name for name in expected_exports if name in export_names]
        if stale:
            raise InitializationError(
                "the task export(s) already exist before the task ran: " + ", ".join(stale)
            )

        return (
            f"the fixture directory carries {len(expected_files)} calibration sources "
            f"with {manifest or 'its manifest'}, and none of the "
            f"{len(expected_exports)} target export(s) is present"
        )
